package at.janic.thedarkdimensions.test;

import at.janic.thedarkdimensions.*;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.server.level.*;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;

final class MindshiftTests {
    private static net.minecraft.world.entity.animal.cow.Cow target(GameTestHelper h){var mob=h.spawn(EntityTypes.COW,new Vec3(5.5,2,10.5));mob.setNoAi(true);mob.getAttribute(Attributes.MAX_HEALTH).setBaseValue(40);mob.setHealth(40);return mob;}
    private static MindshiftBolt bolt(GameTestHelper h,ServerPlayer p,LivingEntity target){var b=Mindshift.BOLT.get().create(h.getLevel(),EntitySpawnReason.EVENT);b.setPos(p.getEyePosition());b.launch(p,target);return b;}
    private static void impact(MindshiftBolt b,LivingEntity target){try{var method=MindshiftBolt.class.getDeclaredMethod("onHitEntity",EntityHitResult.class);method.setAccessible(true);method.invoke(b,new EntityHitResult(target));}catch(Exception e){throw new IllegalStateException(e);}}
    static void cast(GameTestHelper h){try(var f=DefenseTests.player(h,RelicKatanas.MINDSHIFTER.get())){var p=f.player();var target=target(h);p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,target.getEyePosition());
        h.assertTrue(p.getMainHandItem().use(h.getLevel(),p,InteractionHand.MAIN_HAND).consumesAction(),"Right click fires instead of guarding");var projectiles=h.getLevel().getEntitiesOfClass(MindshiftBolt.class,p.getBoundingBox().inflate(3));h.assertTrue(projectiles.size()==1&&projectiles.getFirst().getOwner()==p&&Mindshift.remaining(p)==100&&p.getMainHandItem().getDamageValue()==3,"Native Shulker subclass launches once with five-second recovery and three wear");
        p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(RelicKatanas.MINDSHIFTER.get()));h.assertTrue(!Mindshift.cast(p)&&h.getLevel().getEntitiesOfClass(MindshiftBolt.class,p.getBoundingBox().inflate(3)).size()==1,"Replacing weapon cannot reset the shot cooldown");p.setShiftKeyDown(true);h.assertTrue(p.getMainHandItem().use(h.getLevel(),p,InteractionHand.MAIN_HAND).consumesAction()&&p.isUsingItem(),"Sneak-right-click still guards during projectile cooldown");
        var clone=(ServerPlayer)h.makeMockServerPlayer(net.minecraft.world.level.GameType.SURVIVAL);clone.restoreFrom(p,false);h.assertTrue(clone.getData(Mindshift.READY).equals(p.getData(Mindshift.READY)),"Death/respawn preserves shot recovery");projectiles.forEach(Entity::discard);
    }h.succeed();}
    static void flight(GameTestHelper h){var f=DefenseTests.player(h,RelicKatanas.MINDSHIFTER.get());var p=f.player();var mob=target(h);p.lookAt(net.minecraft.commands.arguments.EntityAnchorArgument.Anchor.EYES,mob.getEyePosition());var a=p.position();var b=mob.position();float yaw=p.getYRot();h.onEachTick(()->h.getLevel().getChunkSource().addTicketWithRadius(TicketType.PORTAL,p.chunkPosition(),2));h.assertTrue(Mindshift.cast(p),"Actual shot launches");
        h.startSequence().thenWaitUntil(()->h.assertTrue(mob.getHealth()<40,"Native homing projectile reaches target"))
          .thenExecute(()->{try(f){h.assertTrue(mob.getHealth()==35&&!mob.hasEffect(MobEffects.LEVITATION),"Shulker hit deals exactly five damage without levitation");h.assertTrue(p.position().distanceToSqr(b)<.04&&mob.position().distanceToSqr(a)<.04,"Confirmed projectile hit exchanges both real positions");h.assertTrue(Math.abs(p.getYRot()-yaw)<.01&&p.getDeltaMovement().lengthSqr()<.01,"Swap preserves view and clears movement");}}).thenSucceed();
    }
    static void blocked(GameTestHelper h){try(var f=DefenseTests.player(h,RelicKatanas.MINDSHIFTER.get())){var p=f.player();var mob=h.spawn(EntityTypes.CHICKEN,new Vec3(5.5,2,10.5));mob.setNoAi(true);mob.getAttribute(Attributes.MAX_HEALTH).setBaseValue(30);mob.setHealth(30);h.setBlock(5,3,10,Blocks.STONE);var a=p.position();var b=mob.position();impact(bolt(h,p,mob),mob);h.assertTrue(mob.getHealth()==25&&!mob.hasEffect(MobEffects.LEVITATION),"Blocked swap still deals projectile damage");h.assertTrue(p.position().equals(a)&&mob.position().equals(b),"Destination fitting a chicken but not a player moves neither participant");}h.succeed();}
    static void canceled(GameTestHelper h){try(var f=DefenseTests.player(h,RelicKatanas.MINDSHIFTER.get())){var p=f.player();var mob=target(h);var a=p.position();var b=mob.position();java.util.function.Consumer<net.neoforged.neoforge.event.entity.EntityTeleportEvent> listener=e->{if(e.getEntity()==mob)e.setCanceled(true);};net.neoforged.neoforge.common.NeoForge.EVENT_BUS.addListener(listener);try{impact(bolt(h,p,mob),mob);h.assertTrue(p.position().equals(a)&&mob.position().equals(b)&&mob.getHealth()==35,"Canceled target teleport prevents a partial swap while retaining hit damage");}finally{net.neoforged.neoforge.common.NeoForge.EVENT_BUS.unregister(listener);}}h.succeed();}
    static void fatal(GameTestHelper h){try(var f=DefenseTests.player(h,RelicKatanas.MINDSHIFTER.get())){var p=f.player();var mob=target(h);mob.setHealth(4);var start=p.position();impact(bolt(h,p,mob),mob);h.assertTrue(!mob.isAlive()&&p.position().equals(start),"Fatal projectile hit never swaps into a dead target");}h.succeed();}
    static void persistence(GameTestHelper h){try(var f=DefenseTests.player(h,RelicKatanas.MINDSHIFTER.get())){var p=f.player();var mob=target(h);var original=bolt(h,p,mob);var out=TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess());h.assertTrue(original.save(out),"Projectile saves with its own registered type");var tag=out.buildResult();h.assertTrue(tag.getStringOr("id","").equals("thedarkdimensions:mindshift_bolt")&&tag.contains("Target"),"Native owner/target routing is persisted under custom entity id");var loaded=EntityType.create(TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess(),tag),h.getLevel(),new EntitySpawnRequest(EntitySpawnReason.LOAD,false)).orElseThrow();h.assertTrue(loaded instanceof MindshiftBolt,"Reload cannot become a vanilla levitation bullet");impact((MindshiftBolt)loaded,mob);h.assertTrue(mob.getHealth()==35&&!mob.hasEffect(MobEffects.LEVITATION),"Reloaded projectile retains damage/swap callback");loaded.discard();}h.succeed();}
    static void unsafe(GameTestHelper h){try(var f=DefenseTests.player(h,RelicKatanas.MINDSHIFTER.get())){var p=f.player();var mob=target(h);h.assertTrue(!Mindshift.mayHit(p,p),"Self-target cannot swap");var a=p.position();var b=mob.position();h.setBlock(5,1,10,Blocks.AIR);h.assertTrue(!Mindshift.swap(p,mob)&&p.position().equals(a)&&mob.position().equals(b),"Unsupported destination prevents swapping");h.setBlock(5,1,10,Blocks.STONE);h.setBlock(5,2,10,Blocks.WATER);h.assertTrue(!Mindshift.swap(p,mob)&&p.position().equals(a),"Fluid destination prevents swapping");h.setBlock(5,2,10,Blocks.AIR);mob.setPos(b.add(40,0,0));h.assertTrue(!Mindshift.swap(p,mob),"Swap enforces a bounded range");}h.succeed();}
    static void scars(GameTestHelper h){var first=DefenseTests.player(h,RelicKatanas.HELLSBLADE.get());var second=DefenseTests.player(h,RelicKatanas.HELLSBLADE.get());var mob=target(h);CrimsonRupture.hit(mob,first.player(),false);CrimsonRupture.hit(mob,first.player(),false);h.assertTrue(CrimsonRupture.stacks(mob,first.player())==1&&!mob.isOnFire(),"Repeated same-swing callbacks cannot add charges or ignite");CrimsonRupture.hit(mob,second.player(),false);h.assertTrue(CrimsonRupture.stacks(mob,first.player())==0&&CrimsonRupture.stacks(mob,second.player())==1,"Another player's strike cannot inherit stored fissures");h.runAfterDelay(81,()->{try(first;second){h.assertTrue(CrimsonRupture.stacks(mob,second.player())==0&&mob.getHealth()==40&&!mob.isOnFire(),"Unused fissures expire after four seconds without damage over time");h.succeed();}});}
    static void animations(GameTestHelper h){if(net.neoforged.fml.ModList.get().isLoaded("player_animation_library"))try{for(String name:List.of("mindshifter_cast","mindshifter_shift"))try(var input=MindshiftTests.class.getResourceAsStream("/assets/thedarkdimensions/player_animations/"+name+".json")){var parsed=(Map<?,?>)Class.forName("com.zigythebird.playeranimcore.loading.UniversalAnimLoader").getMethod("loadAnimations",java.io.InputStream.class).invoke(null,input);h.assertTrue(parsed.containsKey(name),"PAL parses authored End-style animation "+name);}}catch(Exception e){throw new IllegalStateException(e);}h.succeed();}
}

